import sys

def run(theta, step=3, max_iters=30, verbose=True):
    # grid of triangles: angles a,b,c multiples of step, a,b,c>0, a+b+c=180
    # represent triangle as tuple sorted for storage but we need actual (a,b,c) with vertex roles for cutting;
    # since cutting can be done from any of 3 vertices, unordered is fine - we just try all vertex assignments.
    triangles = []
    for a in range(step, 180, step):
        for b in range(step, 180-a, step):
            c = 180 - a - b
            if c <= 0: continue
            if c % step != 0: continue
            triangles.append((a,b,c))
    triangles = list(set(tuple(sorted(t)) for t in triangles))
    def has_theta(t):
        return theta in t
    U = set(t for t in triangles if has_theta(t))
    all_set = set(triangles)
    def canon(a,b,c):
        return tuple(sorted((a,b,c)))

    for it in range(max_iters):
        changed = False
        newly = []
        for t in triangles:
            if t in U: continue
            a,b,c = t
            found = False
            # try cutting from each vertex (angle X), with adjacent angles Y,Z (the "B","C" roles)
            for X, Y, Z in [(a,b,c), (b,a,c), (c,a,b)]:
                # A1 ranges 1..X-1 in steps of `step` (approx grid on the cut point)
                for A1 in range(step, X, step):
                    A2 = X - A1
                    ch1 = canon(Y, A1, Z+A2)
                    ch2 = canon(Z, A2, Y+A1)
                    if ch1 in U and ch2 in U:
                        found = True
                        break
                if found: break
            if found:
                newly.append(t)
        if newly:
            for t in newly:
                U.add(t)
            changed = True
        if verbose:
            print(f"theta={theta} iter={it} |U|={len(U)}/{len(all_set)}")
        if not changed:
            break
    return U, all_set

for theta in [90, 150, 170, 120, 100, 60, 45, 30, 10]:
    U, allset = run(theta, step=4, max_iters=15, verbose=False)
    print(f"theta={theta}: |U|={len(U)} / {len(allset)}  full={len(U)==len(allset)}")

